arguments.content:
/* ===== RESET & BASE ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; }
body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background: #0D1B2A;
  color: #E0E6ED;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}
a { color: inherit; text-decoration: none; }
ul { list-style: none; }
img { max-width: 100%; display: block; }
button, input, textarea, select { font-family: inherit; }

/* ===== UTILITY ===== */
.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
.section-pad { padding: 80px 0; }
.accent { color: #00B4D8; }
.green { color: #6CC24A; }
.btn {
  display: inline-block;
  padding: 14px 32px;
  border-radius: 6px;
  font-weight: 600;
  font-size: 15px;
  cursor: pointer;
  transition: all 0.25s ease;
  border: none;
  text-align: center;
}
.btn-primary {
  background: #00B4D8;
  color: #0D1B2A;
}
.btn-primary:hover { background: #0096B7; }
.btn-secondary {
  background: transparent;
  color: #00B4D8;
  border: 2px solid #00B4D8;
}
.btn-secondary:hover { background: rgba(0,180,216,0.1); }
.btn-green { background: #6CC24A; color: #0D1B2A; }
.btn-green:hover { background: #5AAF38; }
.section-label {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: #00B4D8;
  margin-bottom: 12px;
}
.section-title {
  font-size: 36px;
  font-weight: 700;
  line-height: 1.2;
  margin-bottom: 16px;
}
.section-desc {
  font-size: 17px;
  color: #9CA8B7;
  max-width: 680px;
  line-height: 1.7;
}

/* ===== HEADER / NAV ===== */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(13,27,42,0.95);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid rgba(255,255,255,0.06);
}
.nav { display: flex; align-items: center; justify-content: space-between; height: 72px; }
.nav-logo {
  font-size: 22px;
  font-weight: 700;
  color: #fff;
  display: flex;
  align-items: center;
  gap: 8px;
}
.nav-logo svg { width: 32px; height: 32px; }
.nav-links { display: flex; align-items: center; gap: 32px; }
.nav-links > li { position: relative; }
.nav-links > li > a {
  font-size: 15px;
  font-weight: 500;
  color: #C5CDD8;
  transition: color 0.2s;
  padding: 8px 0;
  display: flex;
  align-items: center;
  gap: 4px;
}
.nav-links > li > a:hover { color: #fff; }
.nav-links .caret { font-size: 10px; transition: transform 0.2s; }
.nav-dropdown { position: relative; }
.nav-dropdown-menu {
  position: absolute;
  top: 100%;
  left: -12px;
  background: #1B2838;
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 8px;
  padding: 8px 0;
  min-width: 220px;
  opacity: 0;
  visibility: hidden;
  transform: translateY(8px);
  transition: all 0.25s ease;
  box-shadow: 0 12px 40px rgba(0,0,0,0.4);
}
.nav-dropdown:hover .nav-dropdown-menu,
.nav-dropdown.active .nav-dropdown-menu {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}
.nav-dropdown-menu a {
  display: block;
  padding: 10px 20px;
  font-size: 14px;
  color: #C5CDD8;
  transition: all 0.15s;
}
.nav-dropdown-menu a:hover { color: #fff; background: rgba(0,180,216,0.1); }
.nav-cta .btn { padding: 10px 24px; font-size: 14px; }

/* Mobile hamburger */
.hamburger { display: none; flex-direction: column; gap: 5px; cursor: pointer; background: none; border: none; padding: 4px; }
.hamburger span { display: block; width: 24px; height: 2px; background: #fff; transition: all 0.3s; }

/* ===== HERO ===== */
.hero {
  padding: 160px 0 100px;
  position: relative;
  overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 800px;
  height: 800px;
  background: radial-gradient(circle, rgba(0,180,216,0.08) 0%, transparent 70%);
  pointer-events: none;
}
.hero-content { position: relative; z-index: 1; max-width: 760px; }
.hero-title {
  font-size: 52px;
  font-weight: 800;
  line-height: 1.1;
  color: #fff;
  margin-bottom: 20px;
  letter-spacing: -0.5px;
}
.hero-subtitle {
  font-size: 19px;
  color: #9CA8B7;
  line-height: 1.7;
  margin-bottom: 36px;
  max-width: 600px;
}
.hero-buttons { display: flex; gap: 16px; flex-wrap: wrap; }

/* ===== FEATURED PRODUCT BANNER ===== */
.featured-banner {
  background: linear-gradient(135deg, #15295A 0%, #1B2838 100%);
  border: 1px solid rgba(0,180,216,0.2);
  border-radius: 12px;
  padding: 40px 48px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  margin-top: -20px;
  position: relative;
  z-index: 2;
}
.featured-banner .featured-label {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 2px;
  color: #6CC24A;
  text-transform: uppercase;
  margin-bottom: 4px;
}
.featured-banner h3 { font-size: 28px; font-weight: 700; color: #fff; margin-bottom: 4px; }
.featured-banner p { color: #9CA8B7; font-size: 15px; }
.featured-banner .btn-green { white-space: nowrap; }

/* ===== USE CASES ===== */
.use-cases { background: #0F2237; }
.use-cases-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 40px;
}
.use-case-card {
  background: rgba(27,40,56,0.6);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: 10px;
  padding: 32px 28px;
  transition: all 0.3s ease;
  cursor: pointer;
}
.use-case-card:hover {
  border-color: rgba(0,180,216,0.3);
  transform: translateY(-4px);
  box-shadow: 0 8px 32px rgba(0,0,0,0.3);
}
.use-case-card .icon-wrap {
  width: 48px;
  height: 48px;
  border-radius: 10px;
  background: rgba(0,180,216,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
}
.use-case-card .icon-wrap svg { width: 24px; height: 24px; stroke: #00B4D8; fill: none; stroke-width: 2; }
.use-case-card h4 { font-size: 17px; font-weight: 600; color: #fff; margin-bottom: 8px; }
.use-case-card p { font-size: 14px; color: #9CA8B7; line-height: 1.6; }

/* ===== INDUSTRY TABS ===== */
.industry-tabs { background: #0D1B2A; }
.tab-bar {
  display: flex;
  gap: 4px;
  background: rgba(27,40,56,0.8);
  border-radius: 8px;
  padding: 4px;
  margin-bottom: 40px;
  overflow-x: auto;
}
.tab-btn {
  padding: 12px 24px;
  border: none;
  background: transparent;
  color: #9CA8B7;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  border-radius: 6px;
  transition: all 0.25s ease;
  white-space: nowrap;
}
.tab-btn:hover { color: #fff; }
.tab-btn.active { background: #00B4D8; color: #0D1B2A; }
.tab-panel { display: none; animation: fadeIn 0.3s ease; }
.tab-panel.active { display: block; }
@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

/* ===== PLATFORM DIAGRAM (SVG) ===== */
.platform-diagram { background: #0D1B2A; padding: 60px 0; }
.diagram-container {
  max-width: 900px;
  margin: 0 auto;
  position: relative;
}
.diagram-pillars {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}
.pillar {
  background: linear-gradient(180deg, #15295A 0%, rgba(21,41,90,0.4) 100%);
  border: 1px solid rgba(0,180,216,0.15);
  border-radius: 12px;
  padding: 36px 28px;
  text-align: center;
  position: relative;
}
.pillar-icon {
  width: 64px;
  height: 64px;
  margin: 0 auto 20px;
  border-radius: 50%;
  background: rgba(0,180,216,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
}
.pillar-icon svg { width: 32px; height: 32px; stroke: #00B4D8; fill: none; stroke-width: 1.5; }
.pillar h4 { font-size: 18px; font-weight: 700; color: #fff; margin-bottom: 8px; }
.pillar p { font-size: 14px; color: #9CA8B7; line-height: 1.6; }
.diagram-connector {
  text-align: center;
  padding: 24px 0;
  color: #00B4D8;
  font-weight: 700;
  font-size: 14px;
  letter-spacing: 2px;
  text-transform: uppercase;
}

/* ===== COMPANY CULTURE ===== */
.culture-section {
  background: linear-gradient(135deg, #15295A 0%, #0D1B2A 100%);
}
.culture-content {
  max-width: 640px;
}
.culture-content .section-title { color: #fff; }

/* ===== RENEWABLES CTA ===== */
.renewables-cta {
  background: #0F2237;
  border-top: 1px solid rgba(0,180,216,0.1);
}
.renewables-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
}
.renewables-content { max-width: 600px; }
.renewables-content .section-title { color: #fff; }

/* ===== PLATFORM BENEFITS ===== */
.benefits-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 28px;
  margin-top: 48px;
}
.benefit-card {
  background: rgba(27,40,56,0.5);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: 10px;
  padding: 28px 24px;
  transition: border-color 0.3s;
}
.benefit-card:hover { border-color: rgba(0,180,216,0.2); }
.benefit-card .num {
  font-size: 40px;
  font-weight: 800;
  color: rgba(0,180,216,0.15);
  line-height: 1;
  margin-bottom: 12px;
}
.benefit-card h4 { font-size: 17px; font-weight: 600; color: #fff; margin-bottom: 8px; }
.benefit-card p { font-size: 14px; color: #9CA8B7; line-height: 1.6; }

/* ===== CIRCULAR STATS ===== */
.stats-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 48px;
  margin-top: 48px;
}
.stat-item { text-align: center; }
.stat-circle {
  width: 160px;
  height: 160px;
  margin: 0 auto 20px;
  position: relative;
}
.stat-circle svg { width: 100%; height: 100%; transform: rotate(-90deg); }
.stat-circle .bg { fill: none; stroke: rgba(255,255,255,0.06); stroke-width: 8; }
.stat-circle .progress { fill: none; stroke: #00B4D8; stroke-width: 8; stroke-linecap: round; transition: stroke-dashoffset 1s ease; }
.stat-circle .value {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-size: 36px;
  font-weight: 800;
  color: #fff;
}
.stat-circle .value span { font-size: 20px; }
.stat-item p { font-size: 15px; color: #9CA8B7; max-width: 200px; margin: 0 auto; }

/* ===== IMPLEMENTATION TIMELINE ===== */
.timeline { margin-top: 48px; }
.timeline-item {
  display: flex;
  align-items: flex-start;
  gap: 24px;
  margin-bottom: 36px;
}
.timeline-duration {
  min-width: 140px;
  text-align: right;
}
.timeline-duration .dur {
  font-size: 24px;
  font-weight: 800;
  color: #00B4D8;
}
.timeline-bar-wrap { flex: 1; }
.timeline-bar {
  height: 12px;
  background: rgba(255,255,255,0.06);
  border-radius: 6px;
  overflow: hidden;
  margin-bottom: 8px;
}
.timeline-bar .fill {
  height: 100%;
  background: linear-gradient(90deg, #00B4D8, #0077B6);
  border-radius: 6px;
  transition: width 1s ease;
}
.timeline-bar-wrap p { font-size: 14px; color: #9CA8B7; }

/* ===== ACCORDION ===== */
.accordion { margin-top: 48px; }
.accordion-item {
  background: rgba(27,40,56,0.5);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: 10px;
  margin-bottom: 12px;
  overflow: hidden;
}
.accordion-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 24px;
  cursor: pointer;
  transition: background 0.2s;
}
.accordion-header:hover { background: rgba(0,180,216,0.05); }
.accordion-header h4 { font-size: 17px; font-weight: 600; color: #fff; display: flex; align-items: center; gap: 12px; }
.accordion-header .chevron {
  width: 24px;
  height: 24px;
  stroke: #9CA8B7;
  fill: none;
  stroke-width: 2;
  transition: transform 0.3s ease;
  flex-shrink: 0;
}
.accordion-item.open .chevron { transform: rotate(180deg); }
.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease;
}
.accordion-body-inner {
  padding: 0 24px 20px;
  font-size: 15px;
  color: #9CA8B7;
  line-height: 1.7;
}

/* ===== DATA LIFECYCLE DIAGRAM ===== */
.lifecycle-diagram {
  background: rgba(27,40,56,0.3);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: 12px;
  padding: 48px;
  margin-top: 48px;
}
.lifecycle-flow {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0;
  flex-wrap: wrap;
}
.lifecycle-step {
  background: #15295A;
  border: 1px solid rgba(0,180,216,0.2);
  border-radius: 8px;
  padding: 16px 24px;
  text-align: center;
  min-width: 140px;
}
.lifecycle-step h5 { font-size: 14px; font-weight: 600; color: #00B4D8; margin-bottom: 4px; }
.lifecycle-step p { font-size: 12px; color: #9CA8B7; }
.lifecycle-arrow {
  font-size: 24px;
  color: #00B4D8;
  padding: 0 8px;
  flex-shrink: 0;
}
.lifecycle-row-label {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: #6CC24A;
  margin-bottom: 16px;
  text-align: center;
}
.lifecycle-row { margin-bottom: 32px; }
.lifecycle-row:last-child { margin-bottom: 0; }

/* ===== TESTIMONIALS CAROUSEL ===== */
.testimonials { background: #0F2237; }
.carousel-wrapper { position: relative; overflow: hidden; margin-top: 40px; }
.carousel-track {
  display: flex;
  transition: transform 0.5s ease;
}
.carousel-slide {
  min-width: 100%;
  padding: 0 16px;
}
.testimonial-card {
  background: rgba(27,40,56,0.6);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: 10px;
  padding: 36px;
  max-width: 700px;
  margin: 0 auto;
}
.testimonial-card .quote {
  font-size: 18px;
  font-style: italic;
  color: #E0E6ED;
  line-height: 1.7;
  margin-bottom: 20px;
  position: relative;
}
.testimonial-card .quote::before {
  content: '\201C';
  font-size: 48px;
  color: #00B4D8;
  position: absolute;
  top: -20px;
  left: -4px;
  line-height: 1;
  opacity: 0.5;
}
.testimonial-card .author { font-size: 14px; color: #9CA8B7; font-weight: 600; }
.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 24px;
}
.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: rgba(255,255,255,0.15);
  cursor: pointer;
  transition: all 0.25s;
  border: none;
}
.carousel-dot.active { background: #00B4D8; transform: scale(1.2); }

/* ===== SECURITY PAGE ===== */
.security-hero {
  background: linear-gradient(135deg, #15295A 0%, #0D1B2A 100%);
  position: relative;
}
.security-hero::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  background: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%2300B4D8' fill-opacity='0.03'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
  pointer-events: none;
}
.security-details { padding: 40px 0 0; }
.security-tab-content {
  background: rgba(27,40,56,0.4);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: 12px;
  padding: 48px;
}
.security-features-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
  margin-top: 32px;
}
.security-feature {
  display: flex;
  gap: 16px;
  padding: 24px;
  background: rgba(13,27,42,0.5);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: 10px;
}
.security-feature .sf-icon {
  width: 44px;
  height: 44px;
  border-radius: 8px;
  background: rgba(0,180,216,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.security-feature .sf-icon svg { width: 22px; height: 22px; stroke: #00B4D8; fill: none; stroke-width: 2; }
.security-feature h4 { font-size: 15px; font-weight: 600; color: #fff; margin-bottom: 4px; }
.security-feature p { font-size: 13px; color: #9CA8B7; line-height: 1.5; }

/* ===== COMPLIANCE CTA ===== */
.compliance-cta {
  background: linear-gradient(135deg, #15295A 0%, #0D1B2A 100%);
  text-align: center;
}

/* ===== INTEGRATION PAGE ===== */
.integration-tab-content {
  background: rgba(27,40,56,0.4);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: 12px;
  padding: 48px;
  margin-top: 32px;
}
.etl-benefits {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 20px;
  margin-top: 32px;
}
.etl-benefit {
  display: flex;
  gap: 12px;
  align-items: flex-start;
  padding: 20px;
  background: rgba(13,27,42,0.5);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: 8px;
}
.etl-benefit .check {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: rgba(108,194,74,0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.etl-benefit .check svg { width: 14px; height: 14px; stroke: #6CC24A; fill: none; stroke-width: 3; }
.etl-benefit h4 { font-size: 15px; font-weight: 600; color: #fff; margin-bottom: 4px; }
.etl-benefit p { font-size: 13px; color: #9CA8B7; line-height: 1.5; }

/* ===== DEMO FORM ===== */
.demo-section {
  min-height: 100vh;
  display: flex;
  align-items: flex-start;
  padding-top: 120px;
}
.demo-form-wrap {
  max-width: 640px;
  margin: 0 auto;
  width: 100%;
}
.demo-form-wrap .section-title { text-align: center; color: #fff; }
.demo-form-wrap .section-desc { text-align: center; margin: 0 auto 40px; }
.demo-form {
  background: rgba(27,40,56,0.5);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: 12px;
  padding: 40px;
}
.form-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 20px;
}
.form-group { display: flex; flex-direction: column; }
.form-group.full-width { grid-column: 1 / -1; }
.form-group label {
  font-size: 13px;
  font-weight: 600;
  color: #9CA8B7;
  margin-bottom: 6px;
}
.form-group label .req { color: #00B4D8; }
.form-group input,
.form-group textarea,
.form-group select {
  background: rgba(13,27,42,0.6);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 6px;
  padding: 12px 16px;
  color: #fff;
  font-size: 15px;
  transition: border-color 0.2s;
}
.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
  outline: none;
  border-color: #00B4D8;
}
.form-group input.error,
.form-group textarea.error {
  border-color: #E74C3C;
}
.form-group .error-msg {
  font-size: 12px;
  color: #E74C3C;
  margin-top: 4px;
  display: none;
}
.form-group input.error + .error-msg,
.form-group textarea.error + .error-msg { display: block; }
.form-group textarea { resize: vertical; min-height: 100px; }
.form-submit {
  margin-top: 24px;
  text-align: center;
}
.form-submit .btn { width: 100%; max-width: 280px; padding: 16px; font-size: 16px; }
.form-success {
  display: none;
  text-align: center;
  padding: 40px;
}
