.support-card h4 { font-size: 16px; font-weight: 600; color: #fff; margin-bottom: 8px; }
.support-card p { font-size: 14px; color: #9CA8B7; line-height: 1.6; }

/* ===== COOKIE BANNER ===== */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: #1B2838;
  border-top: 1px solid rgba(0,180,216,0.15);
  padding: 20px 24px;
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 24px;
  flex-wrap: wrap;
  transform: translateY(100%);
  transition: transform 0.4s ease;
}
.cookie-banner.visible { transform: translateY(0); }
.cookie-banner p { font-size: 14px; color: #9CA8B7; }
.cookie-banner .btn { padding: 10px 24px; font-size: 13px; }

/* ===== FOOTER ===== */
.footer {
  background: #0A1628;
  border-top: 1px solid rgba(255,255,255,0.06);
  padding: 60px 0 32px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 40px;
  margin-bottom: 48px;
}
.footer-col h5 {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: #fff;
  margin-bottom: 16px;
}
.footer-col ul li { margin-bottom: 8px; }
.footer-col ul li a {
  font-size: 14px;
  color: #9CA8B7;
  transition: color 0.2s;
}
.footer-col ul li a:hover { color: #00B4D8; }
.footer-logins {
  display: flex;
  gap: 12px;
  margin-top: 12px;
  flex-wrap: wrap;
}
.footer-logins a {
  font-size: 12px;
  padding: 6px 14px;
  border: 1px solid rgba(255,255,255,0.12);
  border-radius: 4px;
  color: #9CA8B7;
  transition: all 0.2s;
}
.footer-logins a:hover { border-color: #00B4D8; color: #00B4D8; }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.06);
  padding-top: 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 13px;
  color: #5A6A7A;
}

/* ===== RESPONSIVE ===== */
