/* ===== RESET & BASE ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; }
body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background: #0D1B2A;
  color: #E0E6ED;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}
a { color: inherit; text-decoration: none; }
ul { list-style: none; }
img { max-width: 100%; display: block; }
button, input, textarea, select { font-family: inherit; }

/* ===== UTILITY ===== */
.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
.section-pad { padding: 80px 0; }
.accent { color: #00B4D8; }
.green { color: #6CC24A; }
.btn {
  display: inline-block;
  padding: 14px 32px;
  border-radius: 6px;
  font-weight: 600;
  font-size: 15px;
  cursor: pointer;
  transition: all 0.25s ease;
  border: none;
  text-align: center;
}
.btn-primary {
  background: #00B4D8;
  color: #0D1B2A;
}
.btn-primary:hover { background: #0096B7; }
.btn-secondary {
  background: transparent;
  color: #00B4D8;
  border: 2px solid #00B4D8;
}
.btn-secondary:hover { background: rgba(0,180,216,0.1); }
.btn-green { background: #6CC24A; color: #0D1B2A; }
.btn-green:hover { background: #5AAF38; }
.section-label {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: #00B4D8;
  margin-bottom: 12px;
}
.section-title {
  font-size: 36px;
  font-weight: 700;
  line-height: 1.2;
  margin-bottom: 16px;
}
.section-desc {
  font-size: 17px;
  color: #9CA8B7;
  max-width: 680px;
  line-height: 1.7;
}

/* ===== HEADER / NAV ===== */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(13,27,42,0.95);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid rgba(255,255,255,0.06);
}
.nav { display: flex; align-items: center; justify-content: space-between; height: 72px; }
.nav-logo {
  font-size: 22px;
  font-weight: 700;
  color: #fff;
  display: flex;
  align-items: center;
  gap: 8px;
}
.nav-logo svg { width: 32px; height: 32px; }
.nav-links { display: flex; align-items: center; gap: 32px; }
.nav-links > li { position: relative; }
.nav-links > li > a {
  font-size: 15px;
  font-weight: 500;
  color: #C5CDD8;
  transition: color 0.2s;
  padding: 8px 0;
  display: flex;
  align-items: center;
  gap: 4px;
}
.nav-links > li > a:hover { color: #fff; }
.nav-links .caret { font-size: 10px; transition: transform 0.2s; }
.nav-dropdown { position: relative; }
.nav-dropdown-menu {
  position: absolute;
  top: 100%;
  left: -12px;
  background: #1B2838;
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 8px;
  padding: 8px 0;
  min-width: 220px;
  opacity: 0;
  visibility: hidden;
  transform: translateY(8px);
  transition: all 0.25s ease;
  box-shadow: 0 12px 40px rgba(0,0,0,0.4);
}
.nav-dropdown:hover .nav-dropdown-menu,
.nav-dropdown.active .nav-dropdown-menu {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}
.nav-dropdown-menu a {
  display: block;
  padding: 10px 20px;
  font-size: 14px;
  color: #C5CDD8;
  transition: all 0.15s;
}
.nav-dropdown-menu a:hover { color: #fff; background: rgba(0,180,216,0.1); }
.nav-cta .btn { padding: 10px 24px; font-size: 14px; }

/* Mobile hamburger */
.hamburger { display: none; flex-direction: column; gap: 5px; cursor: pointer; background: none; border: none; padding: 4px; }
.hamburger span { display: block; width: 24px; height: 2px; background: #fff; transition: all 0.3s; }

/* ===== HERO ===== */
.hero {
  padding: 160px 0 100px;
  position: relative;
  overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 800px;
  height: 800px;
  background: radial-gradient(circle, rgba(0,180,216,0.08) 0%, transparent 70%);
  pointer-events: none;
}
.hero-content { position: relative; z-index: 1; max-width: 760px; }
.hero-title {
  font-size: 52px;
  font-weight: 800;
  line-height: 1.1;
  color: #fff;
  margin-bottom: 20px;
  letter-spacing: -0.5px;
}
.hero-subtitle {
  font-size: 19px;
  color: #9CA8B7;
  line-height: 1.7;
  margin-bottom: 36px;
  max-width: 600px;
}
.hero-buttons { display: flex; gap: 16px; flex-wrap: wrap; }

/* ===== FEATURED PRODUCT BANNER ===== */
.featured-banner {
  background: linear-gradient(135deg, #15295A 0%, #1B2838 100%);
  border: 1px solid rgba(0,180,216,0.2);
  border-radius: 12px;
  padding: 40px 48px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  margin-top: -20px;
  position: relative;
  z-index: 2;
}
.featured-banner .featured-label {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 2px;
  color: #6CC24A;
  text-transform: uppercase;
  margin-bottom: 4px;
}
.featured-banner h3 { font-size: 28px; font-weight: 700; color: #fff; margin-bottom: 4px; }
.featured-banner p { color: #9CA8B7; font-size: 15px; }
.featured-banner .btn-green { white-space: nowrap; }

/* ===== USE CASES ===== */
.use-cases { background: #0F2237; }
.use-cases-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 40px;
}
.use-case-card {
  background: rgba(27,40,56,0.6);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: 10px;
  padding: 32px 28px;
