}
.lifecycle-step h5 { font-size: 14px; font-weight: 600; color: #00B4D8; margin-bottom: 4px; }
.lifecycle-step p { font-size: 12px; color: #9CA8B7; }
.lifecycle-arrow {
  font-size: 24px;
  color: #00B4D8;
  padding: 0 8px;
  flex-shrink: 0;
}
.lifecycle-row-label {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: #6CC24A;
  margin-bottom: 16px;
  text-align: center;
}
.lifecycle-row { margin-bottom: 32px; }
.lifecycle-row:last-child { margin-bottom: 0; }

/* ===== TESTIMONIALS CAROUSEL ===== */
.testimonials { background: #0F2237; }
.carousel-wrapper { position: relative; overflow: hidden; margin-top: 40px; }
.carousel-track {
  display: flex;
  transition: transform 0.5s ease;
}
.carousel-slide {
  min-width: 100%;
  padding: 0 16px;
}
.testimonial-card {
  background: rgba(27,40,56,0.6);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: 10px;
  padding: 36px;
  max-width: 700px;
  margin: 0 auto;
}
.testimonial-card .quote {
  font-size: 18px;
  font-style: italic;
  color: #E0E6ED;
  line-height: 1.7;
  margin-bottom: 20px;
  position: relative;
}
.testimonial-card .quote::before {
  content: '\201C';
  font-size: 48px;
  color: #00B4D8;
  position: absolute;
  top: -20px;
  left: -4px;
  line-height: 1;
  opacity: 0.5;
}
.testimonial-card .author { font-size: 14px; color: #9CA8B7; font-weight: 600; }
.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 24px;
}
.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: rgba(255,255,255,0.15);
  cursor: pointer;
  transition: all 0.25s;
  border: none;
}
.carousel-dot.active { background: #00B4D8; transform: scale(1.2); }

