.security-feature h4 { font-size: 15px; font-weight: 600; color: #fff; margin-bottom: 4px; }
.security-feature p { font-size: 13px; color: #9CA8B7; line-height: 1.5; }

/* ===== COMPLIANCE CTA ===== */
.compliance-cta {
  background: linear-gradient(135deg, #15295A 0%, #0D1B2A 100%);
  text-align: center;
}

/* ===== INTEGRATION PAGE ===== */
.integration-tab-content {
  background: rgba(27,40,56,0.4);
  border: 1px solid rgba(255,255,255,0.06);
